,p_image_prefix=>nvl(wwv_flow_application_install.get_static_plugin_file_prefix('ITEM TYPE','COM.HASHAAM.SKELETON_3D'),'')
,p_javascript_file_urls=>'#PLUGIN_FILES#js/skeleton3d.min.js?v=1.9.0-a319bc82'
,p_css_file_urls=>'#PLUGIN_FILES#css/skeleton3d.min.css?v=1.9.0-a319bc82'
,p_api_version=>3
,p_render_function=>'skeleton3d_pkg.render'
,p_ajax_function=>'skeleton3d_pkg.ajax'
,p_validation_function=>'skeleton3d_pkg.validation'
