,p_display_sequence=>70
,p_static_id=>'attribute_19'
,p_prompt=>'Shared Catalog Maintainer Condition'
,p_apexlang_name=>'clinicMaintainerCondition'
,p_attribute_type=>'PLSQL FUNCTION BODY BOOLEAN'
,p_is_required=>false
,p_is_translatable=>false
,p_attribute_group_id=>wwv_flow_imp.id(14502628304154823)
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2('Server-side PL/SQL function body returning Boolean. Required for shared maintenance. return true; permits any signed-in user with the selected Clinic Permissions. Use a role check for named maintainers, for example return apex_acl.has_user_role(p_application_id => :APP_ID, p_user_name => :APP_USER, p_role_static_id => ''CLINIC_CATALOG_ADMIN''); Checked at render and every shared write. NULL, FALSE, errors or an empty condition deny changes. Attribute 19 is preserved for existing items.'),null)
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(14616043079593479)
,p_plugin_id=>wwv_flow_imp.id(14493163251601159)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>20
,p_display_sequence=>90
,p_static_id=>'attribute_20'
,p_prompt=>'Specialty Page Item'
,p_apexlang_name=>'specialtyItem'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>false
,p_is_translatable=>false
,p_attribute_group_id=>wwv_flow_imp.id(14493263883601159)
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2('Optional page item containing a specialty code such as CARDIOLOGY, ENT or ALL. Its value overrides Specialty on initial render, and changing the page item updates the viewer. A specific specialty constrains saved anatomical areas on the server and hides the specialty switch; ALL supports records spanning specialties. Empty or unknown values use General Medicine.'),null)
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(14616135307593479)
,p_plugin_id=>wwv_flow_imp.id(14493163251601159)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>21
,p_display_sequence=>150
,p_static_id=>'attribute_21'
,p_prompt=>'Name Item (Optional Fallback)'
,p_apexlang_name=>'patientNameItem'
,p_attribute_type=>'PAGE ITEM'
,p_is_required=>false
,p_is_translatable=>false
,p_attribute_group_id=>wwv_flow_imp.id(14502628304154823)
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2('Not required when patient.name is supplied in the patient JSON. Retained for existing integrations: optional fallback page item for the patient name. Used only when patient.name is missing from Patient Data Source. Prefer putting identity and observations together in the single JSON payload. Display & Prefill Options controls visibility and snapshots.'),null)
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(14616284315593479)
,p_plugin_id=>wwv_flow_imp.id(14493163251601159)
